    schedule_duplicate_slot_title: "复制到第二天", schedule_duplicate_slot_success: "任务已复制到第二天 ✅",
    settings_help_faq_btn: "❓ 帮助和常见问题", help_faq_search_placeholder: "搜索一个词...", help_faq_no_results: "未找到结果",
