    schedule_move_slot_title: "다른 날로 이동", schedule_move_slot_confirm_btn: "이동", schedule_move_slot_empty: "이동하기 전에 이 작업에 제목을 추가하세요", schedule_move_slot_success: "작업이 이동되었습니다 ✅",
