    settings_help_faq_btn: "❓ 도움말 및 FAQ", help_faq_search_placeholder: "단어 검색...", help_faq_no_results: "결과를 찾을 수 없습니다",
    settings_contact_us_btn: "📬 문의하기",
    contact_us_category_bug: "🐛 버그 신고", contact_us_category_feature: "💡 기능 제안", contact_us_category_help: "❓ 앱 사용 도움말", contact_us_category_other: "💬 기타",
