    habits_title: "Abitudini", habits_empty_hint: "Ancora nessuna abitudine - aggiungine una per iniziare a tenere traccia della tua serie.", habits_add_modal_title: "Nuova abitudine", habits_name_placeholder: "es. Bere acqua, Leggere, Meditare...", habits_missing_name: "Dai un nome all'abitudine",
