    onboarding_skip_link: "Pomiń", onboarding_next_btn: "Dalej", onboarding_welcome_title: "Witaj w NOT10.ai!", onboarding_welcome_subtitle: "Jedna aplikacja do zadań, odżywiania, finansów i nawyków - skonfigurujmy wszystko w mniej niż minutę.", onboarding_welcome_btn: "Zaczynajmy", onboarding_country_title: "Skąd jesteś?", onboarding_phone_title: "Numer telefonu (opcjonalnie)", onboarding_phone_subtitle: "Tylko na potrzeby przyszłych aktualizacji - całkowicie opcjonalne, pomiń jeśli wolisz.", onboarding_phone_placeholder: "Numer telefonu", onboarding_goal_title: "Jaki cel masz teraz na myśli?", onboarding_goal_placeholder: "np. Zaoszczędzić na wycieczkę, przebiec 5 km...", onboarding_goal_hint: "Dodamy go do Twojej Tablicy wizji - to też możesz pominąć.", onboarding_tour_offer_title: "Chcesz minutowe zwiedzanie?", onboarding_tour_offer_subtitle: "Pokażemy Ci główne funkcje - zawsze możesz je później znaleźć w Ustawieniach.", onboarding_tour_offer_yes: "Tak, pokaż mi!", onboarding_tour_offer_no: "Nie, dzięki, sam poeksploruję", settings_replay_tour_btn: "🧭 Zwiedzanie aplikacji", tour_notes_title: "Notatki i listy", tour_notes_subtitle: "Zapisz coś i przeciągnij na Dziś, Jutro lub Później.", tour_calendar_title: "Harmonogram i kalendarz", tour_calendar_subtitle: "Wszystkie Twoje wydarzenia i zadania, tygodniowe i miesięczne, w jednym miejscu.", tour_nutrition_title: "Inteligentne odżywianie", tour_nutrition_subtitle: "Opisz, co zjadłeś, albo zrób zdjęcie swojego talerza - AI oszacuje kalorie.", tour_finance_title: "Finanse", tour_finance_subtitle: "Przychody, wydatki, cykliczne opłaty i miesięczny budżet, który odnawia się sam.", tour_sport_title: "Sport i nawyki", tour_sport_subtitle: "Śledź treningi, wodę i codzienne nawyki, wszystko na jeden rzut oka.", tour_vision_title: "Tablica wizji", tour_vision_subtitle: "Wyznaczaj cele, śledź postępy i świętuj każdy osiągnięty kamień milowy.", tour_done_title: "Wszystko gotowe!", tour_done_subtitle: "Czas uczynić ten tydzień swoim.", tour_done_btn: "Zaczynajmy",
