    tables_menu_label: "Tabele", tables_title: "Tabele", tables_empty_hint: "Nie masz jeszcze żadnych tabel - utwórz jedną, aby zacząć.", table_add_modal_title: "Nowa Tabela", table_edit_modal_title: "Edytuj Tabelę", table_name_placeholder: "Nazwa tabeli...", table_icon_label: "Ikona", table_manage_columns_btn: "Kolumny", table_add_row_btn: "+ Dodaj wiersz", table_delete_title: "Usunąć tę tabelę?", table_delete_confirm: "Spowoduje to trwałe usunięcie tabeli, wszystkich jej kolumn i wszystkich wierszy. Tej czynności nie można cofnąć.", table_no_columns_hint: "Nie masz jeszcze żadnych kolumn - dotknij \"Kolumny\", aby dodać pierwszą.", table_no_rows_hint: "Nie masz jeszcze żadnych wierszy - dotknij \"+ Dodaj wiersz\", aby zacząć.", table_manage_columns_title: "Kolumny", table_add_column_btn: "+ Dodaj kolumnę", table_add_column_modal_title: "Nowa Kolumna", table_column_name_placeholder: "Nazwa kolumny...", table_column_type_label: "Typ", table_column_type_text: "Tekst", table_column_type_number: "Liczba", table_column_type_checkbox: "Pole wyboru", table_column_type_select: "Wybór", table_column_type_date: "Data", table_column_delete_title: "Usunąć tę kolumnę?", table_column_delete_confirm: "Spowoduje to trwałe usunięcie kolumny i jej danych w każdym wierszu. Tej czynności nie można cofnąć.", table_column_options_label: "Opcje", table_add_option_btn: "+ Dodaj opcję", table_column_option_placeholder: "Nazwa opcji...", table_column_needs_option_error: "Najpierw dodaj co najmniej jedną opcję.", table_select_cell_picker_title: "Wybierz wartość", table_select_cell_clear: "Wyczyść", table_save_btn: "Zapisz", ai_brain_tab_table: "🗂️ Tabela", table_ai_modal_subtitle: "Opisz tabelę, jaką chcesz (np. \"śledzenie moich inwestycji giełdowych\"), a AI zaprojektuje dla Ciebie kolumny i początkowe wiersze.", table_ai_placeholder: "np. Śledzenie moich inwestycji giełdowych", table_ai_build_btn: "Utwórz Tabelę", table_ai_loading_text: "Tworzenie Twojej tabeli...", ai_table_builder_entry