    onboarding_skip_link: "Přeskočit", onboarding_next_btn: "Další", onboarding_welcome_title: "Vítej v NOT10.ai!", onboarding_welcome_subtitle: "Jedna aplikace pro úkoly, výživu, finance a návyky - pojďme tě nastavit za méně než minutu.", onboarding_welcome_btn: "Pojďme na to", onboarding_country_title: "Odkud jsi?", onboarding_phone_title: "Telefonní číslo (nepovinné)", onboarding_phone_subtitle: "Jen pro budoucí aktualizace - zcela nepovinné, klidně přeskoč.", onboarding_phone_placeholder: "Telefonní číslo", onboarding_goal_title: "Jaký cíl máš teď na mysli?", onboarding_goal_placeholder: "např. Naspořit na výlet, uběhnout 5 km...", onboarding_goal_hint: "Přidáme ho na tvou Vision Board - i tohle můžeš přeskočit.", onboarding_tour_offer_title: "Chceš minutovou prohlídku?", onboarding_tour_offer_subtitle: "Ukážeme ti hlavní funkce - později ji vždy najdeš v Nastavení.", onboarding_tour_offer_yes: "Ano, ukaž mi to!", onboarding_tour_offer_no: "Ne díky, prozkoumám si to sám", settings_replay_tour_btn: "🧭 Prohlídka aplikace", tour_notes_title: "Poznámky a seznamy", tour_notes_subtitle: "Zapiš si něco a přetáhni to na Dnes, Zítra nebo Později.", tour_calendar_title: "Rozvrh a kalendář", tour_calendar_subtitle: "Všechny tvé události a úkoly, týdenní i měsíční, na jednom místě.", tour_nutrition_title: "Chytrá výživa", tour_nutrition_subtitle: "Popiš, co jsi jedl, nebo vyfoť svůj talíř - AI odhadne kalorie.", tour_finance_title: "Finance", tour_finance_subtitle: "Příjmy, výdaje, opakované platby a měsíční rozpočet, který se sám obnovuje.", tour_sport_title: "Sport a návyky", tour_sport_subtitle: "Sleduj tréninky, pitný režim a denní návyky, vše na jeden pohled.", tour_vision_title: "Vision Board", tour_vision_subtitle: "Stanov si cíle, sleduj svůj pokrok a oslav každou dosaženou metu.", tour_done_title: "Vše je připraveno!", tour_done_subtitle: "Je čas udělat z tohoto týdne ten tvůj.", tour_done_btn: "Začít",
